# Bootstrap HTTP-only config — active before TLS cert is issued.
# Replaced by deploy/issue-cert.sh with the full TLS config after certs exist.
# This file never references cert files, so `nginx -t` always passes.

upstream fastapi   { server fastapi:8000; }
upstream signaling { server signaling:8001; }

server {
    listen 80;
    server_name _;

    # ACME webroot challenge — certbot writes challenge tokens here
    location /.well-known/acme-challenge/ {
        root /var/www/certbot;
    }

    location = /health {
        proxy_pass       http://fastapi/health;
        proxy_set_header Host $host;
        access_log       off;
    }

    location /api/ {
        proxy_pass       http://fastapi/api/;
        proxy_set_header Host              $host;
        proxy_set_header X-Real-IP         $remote_addr;
        proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }

    # Signaling WebSocket — path /signal is owned by engine.io in the container
    location /signal {
        proxy_pass         http://signaling;
        proxy_http_version 1.1;
        proxy_set_header   Upgrade    $http_upgrade;
        proxy_set_header   Connection "upgrade";
        proxy_set_header   Host       $host;
        proxy_read_timeout 300s;
        gzip               off;
    }
}

