# ssl.conf.template — Full TLS reverse-proxy config for FamilyLink.
# Do NOT activate this file directly — it contains ${DOMAIN} placeholders.
# Substituted by deploy/issue-cert.sh into nginx/conf.d/familyapp.conf.

upstream fastapi   { server fastapi:8000; }
upstream signaling { server signaling:8001; }

# HTTP: ACME challenge passthrough + permanent redirect to HTTPS
server {
    listen 80;
    server_name ${DOMAIN};

    location /.well-known/acme-challenge/ {
        root /var/www/certbot;
    }

    location / {
        return 301 https://$host$request_uri;
    }
}

# HTTPS
server {
    listen 443 ssl;
    http2 on;
    server_name ${DOMAIN};

    # TLS certificates (issued by deploy/issue-cert.sh via certbot)
    ssl_certificate         /etc/letsencrypt/live/${DOMAIN}/fullchain.pem;
    ssl_certificate_key     /etc/letsencrypt/live/${DOMAIN}/privkey.pem;
    ssl_trusted_certificate /etc/letsencrypt/live/${DOMAIN}/chain.pem;

    # Protocols and ciphers — TLS 1.2/1.3 only
    ssl_protocols             TLSv1.2 TLSv1.3;
    ssl_ciphers               ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305:DHE-RSA-AES128-GCM-SHA256;
