// RegisterScreen.jsx — 4-field signup with inline validation.

function RegisterScreen({ theme = 'dark', initial, showErrors = false }) {
  const t = useT(theme);
  const seed = initial || {};
  const [name, setName] = React.useState(seed.name || '');
  const [phone, setPhone] = React.useState(seed.phone || '');
  const [pwd, setPwd] = React.useState(seed.pwd || '');
  const [pwd2, setPwd2] = React.useState(seed.pwd2 || '');
  const [showPwd, setShowPwd] = React.useState(false);
  const [showPwd2, setShowPwd2] = React.useState(false);
  const [focus, setFocus] = React.useState(null);
  const [touched, setTouched] = React.useState(showErrors ? { name: true, phone: true, pwd: true, pwd2: true } : {});

  const formatPhone = (raw) => {
    const d = raw.replace(/\D/g, '').slice(0, 10);
    const a = d.slice(0, 3), b = d.slice(3, 6), c = d.slice(6, 10);
    if (d.length > 6) return `(${a}) ${b}-${c}`;
    if (d.length > 3) return `(${a}) ${b}`;
    if (d.length > 0) return `(${a}`;
    return '';
  };

  const validate = () => {
    const e = {};
    const nameParts = name.trim().split(/\s+/).filter(Boolean);
    if (!name.trim()) e.name = "We'll need your name to introduce you to family.";
    else if (nameParts.length < 2 || nameParts.some(p => p.length < 2)) e.name = 'Please enter your full name.';

    const digits = phone.replace(/\D/g, '');
    if (!phone) e.phone = "Phone number is required so family can reach you.";
    else if (digits.length !== 10) e.phone = 'Phone number looks invalid.';

    if (!pwd) e.pwd = 'Choose a password.';
    else if (pwd.length < 8) e.pwd = 'Password must be at least 8 characters.';

    if (!pwd2) e.pwd2 = 'Please confirm your password.';
    else if (pwd && pwd2 !== pwd) e.pwd2 = "Passwords don't match.";
    return e;
  };

  const allErrors = validate();
  const errors = {};
  for (const k of Object.keys(allErrors)) if (touched[k]) errors[k] = allErrors[k];

  const errorRow = (msg) => (
    <div style={{
      display: 'flex', alignItems: 'center', gap: 6,
      color: FL_ACCENT.danger, fontSize: 13, fontWeight: 500,
      padding: '7px 4px 0 16px',
    }}>
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round">
        <circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/>
      </svg>
      <span>{msg}</span>
    </div>
  );

  const fieldFrame = (id, content, hasErr, isFocused) => {
    const border = hasErr ? FL_ACCENT.danger : (isFocused ? FL_ACCENT.primary : t.hairline);
    return (
      <div style={{
        position: 'relative', display: 'flex', alignItems: 'stretch',
        background: t.surface, border: `1px solid ${border}`,
        borderRadius: 18, boxShadow: t.innerGlow,
        transition: 'border-color 120ms', minHeight: 60,
      }}>{content}</div>
    );
  };

  const labelStyle = (float, hasErr) => ({
    position: 'absolute', left: 16,
    top: float ? 9 : '50%',
    transform: float ? 'translateY(0)' : 'translateY(-50%)',
    fontSize: float ? 12 : 16, fontWeight: 500,
    color: hasErr ? FL_ACCENT.danger : t.fg2,
    pointerEvents: 'none',
    transition: 'all 120ms cubic-bezier(.2,0,0,1)',
    letterSpacing: 0.2,
  });
  const inputStyle = (right = 16) => ({
    flex: 1, width: '100%', boxSizing: 'border-box',
    background: 'transparent', border: 'none', outline: 'none',
    color: t.fg1, fontFamily: "'Inter', sans-serif", fontSize: 17, fontWeight: 500,
    padding: `22px ${right}px 8px 16px`, letterSpacing: 0.1,
  });

  // US flag (SVG)
  const USFlag = (
    <svg width="22" height="16" viewBox="0 0 22 16" style={{ borderRadius: 3, overflow: 'hidden', flexShrink: 0 }} aria-label="United States">
      <defs><clipPath id={`rclip-${theme}`}><rect width="22" height="16" rx="2"/></clipPath></defs>
      <g clipPath={`url(#rclip-${theme})`}>
        <rect width="22" height="16" fill="#B22234"/>
        {[...Array(7)].map((_, i) => (<rect key={i} y={1.23 * (2 * i + 1)} width="22" height="1.23" fill="#fff"/>))}
        <rect width="10" height="7.4" fill="#3C3B6E"/>
      </g>
    </svg>
  );

  const eye = (on, set) => (
    <button onClick={() => set(!on)} aria-label={on ? 'Hide password' : 'Show password'} style={{
      width: 44, height: 44, borderRadius: 999, border: 'none', cursor: 'pointer',
      background: 'transparent', color: t.fg2,
      display: 'flex', alignItems: 'center', justifyContent: 'center',
    }}>
      {on
        ? <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/></svg>
        : <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>}
    </button>
  );

  const nameFloat = focus === 'name' || name.length > 0;
  const phoneFloat = focus === 'phone' || phone.length > 0;
  const pwdFloat = focus === 'pwd' || pwd.length > 0;
  const pwd2Float = focus === 'pwd2' || pwd2.length > 0;

  const onSubmit = () => {
    setTouched({ name: true, phone: true, pwd: true, pwd2: true });
  };

  return (
    <div style={{ flex: 1, display: 'flex', flexDirection: 'column', background: t.bg, overflow: 'hidden' }}>
      {/* Minimal app bar with back */}
      <div style={{ height: 56, padding: '0 8px', display: 'flex', alignItems: 'center', flexShrink: 0 }}>
        <button aria-label="Back" style={{
          width: 48, height: 48, borderRadius: 999, border: 'none',
          background: 'transparent', color: t.fg1, cursor: 'pointer',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}>
          <Icon name="back" size={22}/>
        </button>
        <div style={{ flex: 1, display: 'flex', justifyContent: 'center', marginRight: 48 }}>
          <svg viewBox="0 0 64 32" width="56" height="28" fill="none">
            <circle cx="20" cy="16" r="11" stroke={FL_ACCENT.primary} strokeWidth="2.5"/>
            <circle cx="36" cy="16" r="11" stroke={t.fg1} strokeWidth="2.5" opacity="0.85"/>
          </svg>
        </div>
      </div>

      <div style={{ flex: 1, overflow: 'auto', padding: '12px 24px 28px', display: 'flex', flexDirection: 'column' }}>
        <div style={{ marginTop: 12, marginBottom: 24 }}>
          <h1 style={{ margin: 0, fontSize: 30, fontWeight: 600, letterSpacing: '-0.02em', color: t.fg1 }}>
            Create your account
          </h1>
          <p style={{ margin: '8px 0 0', fontSize: 15, color: t.fg2, lineHeight: 1.45, maxWidth: '36ch' }}>
            One account keeps you connected to everyone in the family.
          </p>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>

          {/* Full name */}
          <div>
            {fieldFrame('name', (
              <div style={{ flex: 1, position: 'relative', display: 'flex', alignItems: 'center' }}>
                <label style={labelStyle(nameFloat, errors.name)}>Full name</label>
                <input
                  value={name}
                  onChange={e => setName(e.target.value)}
                  onFocus={() => setFocus('name')}
                  onBlur={() => { setFocus(null); setTouched(s => ({ ...s, name: true })); }}
                  autoCapitalize="words" autoComplete="name"
                  style={inputStyle()}
                />
              </div>
            ), errors.name, focus === 'name')}
            {errors.name && errorRow(errors.name)}
          </div>

          {/* Phone */}
          <div>
            {fieldFrame('phone', (
              <>
                <div style={{
                  display: 'flex', alignItems: 'center', gap: 8,
                  padding: '0 12px 0 16px',
                  borderRight: `1px solid ${t.hairline}`,
                  color: t.fg1, fontSize: 16, fontWeight: 500, flexShrink: 0,
                }}>
                  {USFlag}
                  <span style={{ color: t.fg2 }}>+1</span>
                </div>
                <div style={{ flex: 1, position: 'relative', display: 'flex', alignItems: 'center' }}>
                  <label style={labelStyle(phoneFloat, errors.phone)}>Phone number</label>
                  <input
                    value={phone}
                    onChange={e => setPhone(formatPhone(e.target.value))}
                    onFocus={() => setFocus('phone')}
                    onBlur={() => { setFocus(null); setTouched(s => ({ ...s, phone: true })); }}
                    inputMode="numeric"
                    placeholder={phoneFloat ? '(555) 000-0000' : ''}
                    style={inputStyle()}
                  />
                </div>
              </>
            ), errors.phone, focus === 'phone')}
            {errors.phone && errorRow(errors.phone)}
          </div>

          {/* Password */}
          <div>
            {fieldFrame('pwd', (
              <>
                <div style={{ flex: 1, position: 'relative', display: 'flex', alignItems: 'center' }}>
                  <label style={labelStyle(pwdFloat, errors.pwd)}>Password</label>
                  <input
                    value={pwd}
                    onChange={e => setPwd(e.target.value)}
                    onFocus={() => setFocus('pwd')}
                    onBlur={() => { setFocus(null); setTouched(s => ({ ...s, pwd: true })); }}
                    type={showPwd ? 'text' : 'password'}
                    style={{ ...inputStyle(56), letterSpacing: showPwd ? 0.1 : 2 }}
                  />
                </div>
                <div style={{ display: 'flex', alignItems: 'center', padding: '0 8px', flexShrink: 0 }}>{eye(showPwd, setShowPwd)}</div>
              </>
            ), errors.pwd, focus === 'pwd')}
            {errors.pwd
              ? errorRow(errors.pwd)
              : (pwdFloat && (
                <div style={{ fontSize: 13, color: t.fg2, padding: '7px 4px 0 16px' }}>
                  At least 8 characters.
                </div>
              ))}
          </div>

          {/* Confirm password */}
          <div>
            {fieldFrame('pwd2', (
              <>
                <div style={{ flex: 1, position: 'relative', display: 'flex', alignItems: 'center' }}>
                  <label style={labelStyle(pwd2Float, errors.pwd2)}>Confirm password</label>
                  <input
                    value={pwd2}
                    onChange={e => setPwd2(e.target.value)}
                    onFocus={() => setFocus('pwd2')}
                    onBlur={() => { setFocus(null); setTouched(s => ({ ...s, pwd2: true })); }}
                    type={showPwd2 ? 'text' : 'password'}
                    style={{ ...inputStyle(56), letterSpacing: showPwd2 ? 0.1 : 2 }}
                  />
                </div>
                <div style={{ display: 'flex', alignItems: 'center', padding: '0 8px', flexShrink: 0 }}>{eye(showPwd2, setShowPwd2)}</div>
              </>
            ), errors.pwd2, focus === 'pwd2')}
            {errors.pwd2 && errorRow(errors.pwd2)}
          </div>
        </div>

        <button
          onClick={onSubmit}
          style={{
            marginTop: 24,
            width: '100%', height: 56,
            borderRadius: 999, border: 'none',
            background: FL_ACCENT.primary, color: '#fff',
            fontFamily: "'Inter', sans-serif", fontSize: 17, fontWeight: 600,
            cursor: 'pointer',
            display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 10,
            boxShadow: '0 8px 24px rgba(91,124,250,0.25)',
          }}
        >Continue</button>

        <p style={{
          margin: '14px 4px 0', fontSize: 12, color: t.fg3,
          textAlign: 'center', lineHeight: 1.45,
        }}>
          By continuing, you agree to our <span style={{ color: t.fg2, fontWeight: 500 }}>Terms</span> and <span style={{ color: t.fg2, fontWeight: 500 }}>Privacy notice</span>.
        </p>

        <div style={{ flex: 1 }} />

        <div style={{
          marginTop: 24, paddingTop: 18,
          borderTop: `1px solid ${t.hairline}`,
          textAlign: 'center',
        }}>
          <button style={{
            border: 'none', background: 'transparent', cursor: 'pointer',
            color: FL_ACCENT.primary, fontFamily: "'Inter', sans-serif",
            fontSize: 15, fontWeight: 600, padding: 0,
            whiteSpace: 'nowrap',
          }}>← Back to login</button>
        </div>
      </div>
    </div>
  );
}

Object.assign(window, { RegisterScreen });

