// OtpScreen.jsx — 6-digit verification with countdown.

function OtpScreen({ theme = 'dark', phone = '+880 1XXX-XXX123', initial = '', initialCountdown = 42, debug = true }) {
  const t = useT(theme);
  const [code, setCode] = React.useState(initial);
  const [countdown, setCountdown] = React.useState(initialCountdown);
  const [focused, setFocused] = React.useState(true);
  const inputRef = React.useRef(null);

  React.useEffect(() => {
    if (countdown <= 0) return;
    const id = setInterval(() => setCountdown(c => Math.max(0, c - 1)), 1000);
    return () => clearInterval(id);
  }, [countdown]);

  const cleanedCode = code.replace(/\D/g, '').slice(0, 6);
  const activeIndex = cleanedCode.length;
  const filled = cleanedCode.length === 6;

  const focus = () => inputRef.current && inputRef.current.focus();

  const fmtCountdown = (s) => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;

  return (
    <div style={{ flex: 1, display: 'flex', flexDirection: 'column', background: t.bg, overflow: 'hidden' }}>
      {/* App bar: back + centered mark */}
      <div style={{ height: 56, padding: '0 8px', display: 'flex', alignItems: 'center', flexShrink: 0 }}>
        <button aria-label="Back" style={{
          width: 48, height: 48, borderRadius: 999, border: 'none',
          background: 'transparent', color: t.fg1, cursor: 'pointer',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}>
          <Icon name="back" size={22}/>
        </button>
        <div style={{ flex: 1, display: 'flex', justifyContent: 'center', marginRight: 48 }}>
          <svg viewBox="0 0 64 32" width="56" height="28" fill="none">
            <circle cx="20" cy="16" r="11" stroke={FL_ACCENT.primary} strokeWidth="2.5"/>
            <circle cx="36" cy="16" r="11" stroke={t.fg1} strokeWidth="2.5" opacity="0.85"/>
          </svg>
        </div>
      </div>

      <div style={{ flex: 1, overflow: 'auto', padding: '20px 24px 28px', display: 'flex', flexDirection: 'column' }}>
        <div style={{ marginTop: 16, marginBottom: 32 }}>
          <h1 style={{ margin: 0, fontSize: 30, fontWeight: 600, letterSpacing: '-0.02em', color: t.fg1 }}>
            Verify your number
          </h1>
          <p style={{ margin: '10px 0 0', fontSize: 15, color: t.fg2, lineHeight: 1.5 }}>
            We sent a code to <span style={{ color: t.fg1, fontWeight: 600 }}>{phone}</span>.
            Enter it below to continue.
          </p>
        </div>

        {/* Segmented input */}
        <div onClick={focus} style={{
          display: 'grid', gridTemplateColumns: 'repeat(6, 1fr)', gap: 8,
          marginBottom: 18, cursor: 'text',
        }}>
          {[0,1,2,3,4,5].map(i => {
            const ch = cleanedCode[i] || '';
            const isActive = focused && i === activeIndex && !filled;
            const isFilled = !!ch;
            const border = isActive ? FL_ACCENT.primary : t.hairline;
            return (
              <div key={i} style={{
                height: 60, borderRadius: 16,
                background: t.surface,
                border: `${isActive ? 2 : 1}px solid ${border}`,
                boxShadow: isActive
                  ? `0 0 0 4px rgba(91,124,250,0.14), ${t.innerGlow}`
                  : t.innerGlow,
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                fontFamily: "'Inter', sans-serif",
                fontSize: 26, fontWeight: 600, color: t.fg1,
                position: 'relative',
                transition: 'border-color 120ms, box-shadow 120ms',
              }}>
                {isFilled
                  ? ch
                  : (isActive && (
                    <span style={{
                      display: 'block', width: 2, height: 26, background: FL_ACCENT.primary,
                      borderRadius: 1, animation: 'fl-otp-caret 1.05s steps(2) infinite',
                    }}/>
                  ))}
              </div>
            );
          })}
        </div>

        {/* Hidden input that captures typing */}
        <input
          ref={inputRef}
          autoFocus
          value={cleanedCode}
          onChange={e => setCode(e.target.value)}
          onFocus={() => setFocused(true)}
          onBlur={() => setFocused(false)}
          inputMode="numeric"
          maxLength={6}
          aria-label="Verification code"
          style={{
            position: 'absolute', opacity: 0, pointerEvents: 'none',
            width: 1, height: 1, left: -9999,
          }}
        />

        {/* Resend row */}
        <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', gap: 6, marginBottom: 12 }}>
          <span style={{ color: t.fg2, fontSize: 14 }}>Didn't get it?</span>
          {countdown > 0 ? (
            <span style={{ color: t.fg3, fontSize: 14, fontWeight: 600 }}>
              Resend in <span style={{ fontVariantNumeric: 'tabular-nums' }}>{fmtCountdown(countdown)}</span>
            </span>
          ) : (
            <button onClick={() => setCountdown(initialCountdown || 45)} style={{
              border: 'none', background: 'transparent', cursor: 'pointer',
              color: FL_ACCENT.primary, fontFamily: "'Inter', sans-serif",
              fontSize: 14, fontWeight: 600, padding: 0,
            }}>Resend code</button>
          )}
        </div>

        {debug && (
          <div style={{ display: 'flex', justifyContent: 'center', marginTop: 6, marginBottom: 4 }}>
            <div style={{
              display: 'inline-flex', alignItems: 'center', gap: 8,
              padding: '6px 12px', borderRadius: 999,
              border: `1px dashed ${t.hairlineStrong}`,
              fontFamily: "'SF Mono', 'JetBrains Mono', Menlo, ui-monospace, monospace",
              fontSize: 12, color: t.fg2, letterSpacing: 0.4,
              background: t.surfaceLo,
            }}>
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke={t.fg2} strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round">
                <circle cx="12" cy="12" r="10"/>
                <path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3"/>
                <line x1="12" y1="17" x2="12.01" y2="17"/>
              </svg>
              Debug OTP: <span style={{ color: t.fg1, fontWeight: 600 }}>123456</span>
            </div>
          </div>
        )}

        <div style={{ flex: 1, minHeight: 12 }} />

        <button
          disabled={!filled}
          style={{
            width: '100%', height: 56,
            borderRadius: 999, border: 'none',
            background: filled ? FL_ACCENT.primary : t.surfaceHi,
            color: filled ? '#fff' : t.fg3,
            fontFamily: "'Inter', sans-serif", fontSize: 17, fontWeight: 600,
            cursor: filled ? 'pointer' : 'default',
            display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 10,
            transition: 'background 120ms, color 120ms',
            boxShadow: filled ? '0 8px 24px rgba(91,124,250,0.25)' : 'none',
          }}
        >Verify</button>

        <button style={{
          marginTop: 14,
          width: '100%', height: 48,
          borderRadius: 999,
          background: 'transparent', color: t.fg2,
          border: 'none', cursor: 'pointer',
          fontFamily: "'Inter', sans-serif", fontSize: 14, fontWeight: 500,
        }}>Wrong number? Change it</button>
      </div>

      <style>{`@keyframes fl-otp-caret { 50% { opacity: 0; } }`}</style>
    </div>
  );
}

Object.assign(window, { OtpScreen });

