// Bars.jsx — AppBar, BottomNav, FAB. Theme-aware via prop.

function AppBar({ title, theme = 'dark', leading, trailing, large = false }) {
  const t = useT(theme);
  if (large) {
    return (
      <div style={{ padding: '8px 16px 16px', background: t.bg }}>
        <div style={{ height: 56, display: 'flex', alignItems: 'center', gap: 4 }}>
          {leading}
          <div style={{ flex: 1 }} />
          {trailing}
        </div>
        <div style={{
          fontSize: 28, fontWeight: 600, letterSpacing: '-0.01em',
          color: t.fg1, padding: '0 4px',
        }}>{title}</div>
      </div>
    );
  }
  return (
    <div style={{
      height: 56, padding: '0 8px',
      display: 'grid',
      gridTemplateColumns: '48px 1fr auto',
      alignItems: 'center', gap: 4, background: t.bg, flexShrink: 0,
    }}>
      <div style={{ display: 'flex', justifyContent: 'flex-start' }}>{leading || <span style={{width:48}}/>}</div>
      <div style={{ fontSize: 20, fontWeight: 600, color: t.fg1, paddingLeft: leading ? 0 : 8 }}>{title}</div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 0 }}>{trailing}</div>
    </div>
  );
}

function IconButton({ icon, onClick, theme = 'dark', active = false, size = 48, iconSize = 22, danger, success, filled }) {
  const t = useT(theme);
  let bg = 'transparent';
  let color = t.fg1;
  if (filled === 'primary') { bg = FL_ACCENT.primary; color = '#fff'; }
  else if (filled === 'danger') { bg = FL_ACCENT.danger; color = '#fff'; }
  else if (filled === 'success') { bg = FL_ACCENT.success; color = '#fff'; }
  else if (active) { color = FL_ACCENT.primary; }
  if (danger && !filled) color = FL_ACCENT.danger;
  if (success && !filled) color = FL_ACCENT.success;
  return (
    <button onClick={onClick} style={{
      width: size, height: size, borderRadius: 999, border: 'none', cursor: 'pointer',
      background: bg, color, display: 'flex', alignItems: 'center', justifyContent: 'center',
