import 'package:dio/dio.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../config/app_config.dart';
import '../storage/secure_storage.dart';
import 'token_interceptor.dart';

// ── Placeholder auth state ────────────────────────────────────────────────────
// Expanded in prompt 12 with real login/logout logic.

class AuthState {
  final String? accessToken;
  const AuthState({this.accessToken});
}

class AuthNotifier extends StateNotifier<AuthState> {
  AuthNotifier() : super(const AuthState());

  void setAccessToken(String token) =>
      state = AuthState(accessToken: token);

  void clear() => state = const AuthState();
}

final authStateProvider =
    StateNotifierProvider<AuthNotifier, AuthState>((_) => AuthNotifier());

// ── Dio client ────────────────────────────────────────────────────────────────

final dioProvider = Provider<Dio>((ref) {
  final secure = ref.watch(secureStorageProvider);

  final interceptor = TokenInterceptor(
    getAccessToken: () => ref.read(authStateProvider).accessToken,
    // TODO: prompt 12 — replace with real refresh implementation
    refreshTokens: () async {
      final refreshToken = await secure.readRefreshToken();
      final deviceId = await secure.readDeviceId();
      if (refreshToken == null) return false;

      try {
        // Bypass the token interceptor by using a standalone Dio instance.
        final plain = Dio(BaseOptions(baseUrl: AppConfig.apiBaseUrl));
        final resp = await plain.post<Map<String, dynamic>>(
          '/api/auth/refresh',
          data: {'refresh_token': refreshToken, 'device_id': deviceId},
        );
        final newAccess = resp.data?['access_token'] as String?;
        final newRefresh = resp.data?['refresh_token'] as String?;
        if (newAccess == null || newRefresh == null) return false;

        ref.read(authStateProvider.notifier).setAccessToken(newAccess);
        await secure.saveRefreshToken(newRefresh);
        return true;
      } catch (_) {
        return false;
      }
    },
    onAuthExpired: () async {
      await secure.deleteRefreshToken();
      ref.read(authStateProvider.notifier).clear();
      // TODO: prompt 12 — navigate to /login via GoRouter
    },
  );

  return Dio(
    BaseOptions(
      baseUrl: AppConfig.apiBaseUrl,
      connectTimeout: const Duration(seconds: 10),
      receiveTimeout: const Duration(seconds: 30),
      headers: {'Content-Type': 'application/json'},
    ),
  )..interceptors.add(interceptor);
});

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import 'core/config/theme.dart';
import 'core/network/dio_client.dart';

// GoRouter reads auth state synchronously; prompt 12 will replace the
// redirect logic once the real auth flow is wired.
final _routerProvider = Provider<GoRouter>((ref) {
  final authState = ref.watch(authStateProvider);

  return GoRouter(
    initialLocation: '/splash',
    redirect: (context, state) {
      final loggedIn = authState.accessToken != null;
      final onAuthRoute = state.matchedLocation == '/login' ||
          state.matchedLocation == '/register' ||
          state.matchedLocation == '/otp' ||
          state.matchedLocation == '/splash';

      // TODO: prompt 12 — expand with persistent session check on splash
      if (!loggedIn && !onAuthRoute) return '/login';
      return null;
    },
    routes: [
      GoRoute(
        path: '/splash',
        builder: (_, __) => const _Placeholder('Splash'),
      ),
      GoRoute(
        path: '/login',
        builder: (_, __) => const _Placeholder('Login'),
      ),
      GoRoute(
        path: '/register',
        builder: (_, __) => const _Placeholder('Register'),
      ),
      GoRoute(
        path: '/otp',
        builder: (_, __) => const _Placeholder('OTP Verification'),
      ),
      GoRoute(
        path: '/home',
        builder: (_, __) => const _Placeholder('Home'),
      ),
      GoRoute(
        path: '/chat/:conversationId',
        builder: (_, state) =>
            _Placeholder('Chat ${state.pathParameters['conversationId']}'),
      ),
      GoRoute(
        path: '/call/incoming',
        builder: (_, __) => const _Placeholder('Incoming Call'),
      ),
      GoRoute(
        path: '/call/active',
        builder: (_, __) => const _Placeholder('Active Call'),
      ),
      GoRoute(
        path: '/contacts',
        builder: (_, __) => const _Placeholder('Contacts'),
      ),
      GoRoute(
        path: '/profile',
        builder: (_, __) => const _Placeholder('Profile'),
      ),
    ],
  );
});

class FamilyLinkApp extends ConsumerWidget {
  const FamilyLinkApp({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final router = ref.watch(_routerProvider);
    return MaterialApp.router(
      title: 'FamilyLink',
      theme: AppTheme.light,
      darkTheme: AppTheme.dark,
      routerConfig: router,
      debugShowCheckedModeBanner: false,
    );
  }
}

class _Placeholder extends StatelessWidget {
  final String name;
  const _Placeholder(this.name);

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(name)),
      body: Center(
        child: Text(
          name,
          style: Theme.of(context).textTheme.headlineMedium,
        ),
      ),
    );
  }
}

