          child: Form(
            key: _formKey,
            autovalidateMode: AutovalidateMode.disabled,
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const SizedBox(height: 64),
                Text(
                  'Create your account',
                  style: TextStyle(
                    fontSize: 30,
                    fontWeight: FontWeight.w600,
                    color: isDark ? AppColors.darkFg1 : AppColors.lightFg1,
                    height: 1.15,
                  ),
                ),
                const SizedBox(height: 8),
                Text(
                  'Join your family on FamilyLink',
                  style: TextStyle(
                    fontSize: 16,
                    color: isDark ? AppColors.darkFg2 : AppColors.lightFg2,
                  ),
                ),
                const SizedBox(height: 40),

                // ── Full name ─────────────────────────────────────────────
                Focus(
                  onFocusChange: (hasFocus) {
                    if (!hasFocus) setState(() => _touched.add('name'));
                  },
                  child: FlTextField(
                    label: 'Full name',
                    controller: _nameCtrl,
                    textInputAction: TextInputAction.next,
                    validator: _touched.contains('name') ? _validateName : null,
                    onChanged: (_) =>
                        _touched.contains('name') ? setState(() {}) : null,
                  ),
                ),
                const SizedBox(height: 16),

                // ── Phone ─────────────────────────────────────────────────
                Focus(
                  onFocusChange: (hasFocus) {
                    if (!hasFocus) setState(() => _touched.add('phone'));
                  },
                  child: FlTextField(
                    label: 'Phone number',
                    controller: _phoneCtrl,
                    hint: '(555) 000-0000',
                    keyboardType: TextInputType.phone,
                    textInputAction: TextInputAction.next,
                    prefixWidget: const PhonePrefix(),
                    inputFormatters: [
                      FilteringTextInputFormatter.digitsOnly,
                      LengthLimitingTextInputFormatter(10),
                    ],
                    validator:
                        _touched.contains('phone') ? _validatePhone : null,
                  ),
                ),
                const SizedBox(height: 16),

                // ── Password ──────────────────────────────────────────────
                Focus(
                  onFocusChange: (hasFocus) {
                    if (!hasFocus) setState(() => _touched.add('password'));
                  },
                  child: FlTextField(
                    label: 'Password',
                    controller: _passwordCtrl,
                    obscureText: true,
                    showToggle: true,
                    textInputAction: TextInputAction.next,
                    hint: 'At least 8 characters',
                    validator: _touched.contains('password')
                        ? _validatePassword
                        : null,
                  ),
                ),
                const SizedBox(height: 16),

                // ── Confirm password ──────────────────────────────────────
                Focus(
                  onFocusChange: (hasFocus) {
                    if (!hasFocus) setState(() => _touched.add('confirm'));
                  },
                  child: FlTextField(
                    label: 'Confirm password',
                    controller: _confirmCtrl,
                    obscureText: true,
                    showToggle: true,
                    textInputAction: TextInputAction.done,
                    onFieldSubmitted: (_) => _submit(),
                    validator: _touched.contains('confirm')
                        ? _validateConfirm
                        : null,
                  ),
                ),

                const SizedBox(height: 32),
                FlButton(
                  label: 'Create account',
                  onPressed: _isLoading ? null : _submit,
                  isLoading: _isLoading,
                ),
                const SizedBox(height: 28),

                // ── Back to login ─────────────────────────────────────────
                Center(
                  child: GestureDetector(
                    onTap: () => context.go('/login'),
                    child: Row(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Icon(
                          Icons.arrow_back,
                          size: 16,
                          color: isDark ? AppColors.darkFg2 : AppColors.lightFg2,
                        ),
                        const SizedBox(width: 4),
                        Text(
                          'Back to login',
                          style: TextStyle(
                            fontSize: 15,
                            color: AppColors.primary,
                            fontWeight: FontWeight.w500,
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
                const SizedBox(height: 32),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

